@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=Rajdhani:wght@400;500;600;700&display=swap');
:root{--cyan:#5beaff;--cyan2:#11b9da;--orange:#ff6b3d;--ink:#07101a;--white:#effaff}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#050910;color:var(--white);font-family:'Rajdhani',sans-serif}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#080e18;isolation:isolate}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.scanlines{position:absolute;inset:0;pointer-events:none;z-index:2;opacity:.14;background:repeating-linear-gradient(0deg,transparent 0 3px,rgba(0,0,0,.26) 4px 5px);mix-blend-mode:multiply}.topbar{position:absolute;z-index:4;top:0;left:0;right:0;height:74px;padding:17px 4.2vw;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(4,8,15,.88),transparent)}.brand{display:flex;align-items:center;gap:11px;font:800 21px 'Barlow Condensed',sans-serif;letter-spacing:1.6px;line-height:.82}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--cyan);color:var(--cyan);font-size:13px;letter-spacing:-.7px;transform:skew(-8deg);box-shadow:0 0 17px #25c9ff36}.brand-light{font-weight:500;color:#b8d5df}.brand small{display:block;color:#809ba9;font:600 8px 'Rajdhani',sans-serif;letter-spacing:2px;margin-top:7px}.mission-tag{font-size:12px;letter-spacing:1.3px;color:#d4e4e9;font-weight:700}.mission-tag i,.eyebrow span{display:inline-block;width:6px;height:6px;margin-right:8px;background:var(--orange);box-shadow:0 0 12px var(--orange);transform:rotate(45deg)}.mission-tag span{color:#65818e}.icon-btn{background:transparent;border:1px solid #b9d1da33;padding:7px 10px;color:var(--cyan);font-size:13px;letter-spacing:1px}.icon-btn span{font-size:9px;color:#a9c2ce}.hud{position:absolute;z-index:3;inset:80px 4.2vw 0;pointer-events:none;text-shadow:0 2px 6px #000}.hud-left{position:absolute;left:0;top:4px;display:flex;gap:27px}.readout{min-width:118px}.micro-label{display:block;color:#80a1ae;font:700 9px 'Rajdhani',sans-serif;letter-spacing:1.9px}.readout strong{font:700 32px 'Barlow Condensed',sans-serif;letter-spacing:1px}.readout small{font-size:11px;color:#a7c4ce;letter-spacing:1px}.speed-track{width:103px;height:2px;background:#a5c4d333;margin-top:0}.speed-track i{height:100%;display:block;width:40%;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}.distance-readout{border-left:1px solid #d5faff30;padding-left:17px;margin-top:4px}.distance-readout strong{font-size:24px}.objective{position:absolute;top:1px;left:50%;transform:translateX(-50%);display:flex;gap:10px;align-items:center;white-space:nowrap}.objective-icon{color:var(--orange);font-size:19px;text-shadow:0 0 13px var(--orange)}.objective strong{display:block;font:700 13px 'Barlow Condensed',sans-serif;letter-spacing:1.35px}.objective small{display:block;color:#91aeb8;font-size:9px;letter-spacing:1.4px;margin-top:2px}.hud-right{position:absolute;right:0;top:4px;display:flex;gap:27px;align-items:center;text-align:right}.weapon strong{display:block;font:700 22px 'Barlow Condensed',sans-serif}.weapon strong small{font-size:10px;color:#a4bfca;letter-spacing:1px}.ammo-pips{display:flex;justify-content:flex-end;gap:3px;margin-top:2px}.ammo-pips i{width:8px;height:2px;background:var(--cyan);box-shadow:0 0 5px #5beaff70}.wave{font-size:9px;letter-spacing:1px;color:#8aa7b0}.wave b{display:block;font:700 14px 'Barlow Condensed';color:#d8f6fb}.threat-bars{display:flex;gap:3px;justify-content:flex-end;margin-top:4px}.threat-bars i{width:13px;height:3px;background:#f66b47}.vitals,.nitro{position:absolute;bottom:42px;width:180px}.vitals{left:0}.nitro{right:0;text-align:right}.armor-bar,.nitro-bar{height:5px;margin:5px 0;background:#c1e6ef36;clip-path:polygon(0 0,100% 0,96% 100%,0 100%)}.armor-bar i,.nitro-bar i{display:block;width:100%;height:100%;background:linear-gradient(90deg,#22b8d1,var(--cyan));box-shadow:0 0 10px var(--cyan);transition:width .2s}.vitals b{font:700 13px 'Barlow Condensed';color:var(--cyan)}.nitro-bar i{background:linear-gradient(90deg,#f36d3e,#ffc15c);box-shadow:0 0 10px #ff8a40}.nitro span:last-child{font-size:9px;letter-spacing:1.6px;color:#ffd2a5}.bottom-hint{position:absolute;z-index:4;bottom:15px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#97acb5;font-size:10px;letter-spacing:1.1px}.bottom-hint span,.controls-note span{color:#dcfaff;font-weight:700}.bottom-hint b{color:var(--orange);padding:0 8px}.crosshair{display:none;position:absolute;z-index:3;width:30px;height:30px;pointer-events:none;transform:translate(-50%,-50%);filter:drop-shadow(0 0 4px #31dcff)}.crosshair i,.crosshair b,.crosshair em,.crosshair span{position:absolute;display:block;background:var(--cyan)}.crosshair i{width:1px;height:8px;top:0;left:14px}.crosshair b{width:1px;height:8px;bottom:0;left:14px}.crosshair em{width:8px;height:1px;left:0;top:14px}.crosshair span{width:8px;height:1px;right:0;top:14px}.toast{position:absolute;left:50%;top:24%;transform:translate(-50%,-10px);font:700 12px 'Barlow Condensed';letter-spacing:2px;color:var(--cyan);opacity:0;transition:.25s;text-shadow:0 0 14px var(--cyan)}.toast.show{opacity:1;transform:translate(-50%,0)}.overlay{position:absolute;z-index:6;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,rgba(4,9,16,.91) 0%,rgba(4,9,16,.76) 42%,rgba(4,9,16,.08) 100%);transition:opacity .45s,visibility .45s}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.intro-card{width:min(440px,90vw);margin-left:-39vw;margin-top:2vh;position:relative}.eyebrow{font-size:10px;letter-spacing:2.5px;color:#a7bdc5;font-weight:700}.intro-card h1{font:900 clamp(76px,10vw,128px)/.77 'Barlow Condensed',sans-serif;letter-spacing:-3px;margin:27px 0 19px;text-shadow:0 8px 45px #000}.intro-card h1 em{font-style:normal;color:var(--cyan);text-shadow:0 0 28px #18c9ed52}.tagline{font:600 16px/1.35 'Barlow Condensed';letter-spacing:2px;margin:0 0 19px;color:#c5d5da}.tagline b{color:white}.intro-rule{width:56px;height:2px;background:var(--orange);box-shadow:0 0 10px #ff6b3d;margin-bottom:15px}.briefing{max-width:390px;color:#9eb3bd;font-size:13px;line-height:1.5;margin:0 0 22px}.briefing b{color:#d6e8ed;font-size:10px;letter-spacing:1.7px}.start-btn{display:flex;align-items:center;justify-content:space-between;width:182px;padding:13px 15px 12px;border:0;background:var(--cyan);color:#06121b;font:800 15px 'Barlow Condensed';letter-spacing:2.2px;cursor:pointer;clip-path:polygon(0 0,92% 0,100% 30%,100% 100%,0 100%);transition:transform .2s,filter .2s}.start-btn:hover{transform:translateY(-2px);filter:brightness(1.17)}.start-btn b{font-size:17px}.controls-note{margin-top:19px;color:#7f99a4;font-size:9px;letter-spacing:1px;white-space:nowrap}.controls-note i{color:var(--orange);font-style:normal;padding:0 4px}.side-stats{position:absolute;right:6vw;bottom:12vh;border-left:1px solid #a6c2c636;padding-left:17px;display:flex;gap:30px;color:#77919d}.side-stats div{display:flex;gap:9px;align-items:center}.side-stats b{font:700 26px 'Barlow Condensed';color:var(--cyan)}.side-stats span{font-size:9px;letter-spacing:1px;line-height:1.2}.version{position:absolute;left:4.2vw;bottom:20px;font-size:8px;letter-spacing:1.6px;color:#617d89}.version span{margin-left:15px;color:#3e5863}.end-card{width:min(440px,90vw);padding:32px;background:rgba(7,15,24,.92);border:1px solid #70dff532;box-shadow:0 0 80px #00131e;clip-path:polygon(0 0,94% 0,100% 7%,100% 100%,0 100%)}.end-card h2{font:800 50px 'Barlow Condensed';margin:12px 0 0;letter-spacing:1px}.end-card>p{color:#9eb6c1;margin:4px 0 24px}.score-grid{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid #c5f7ff26;border-bottom:1px solid #c5f7ff26;padding:16px 0;margin-bottom:22px}.score-grid div+div{border-left:1px solid #c5f7ff26;padding-left:14px}.score-grid span{display:block;color:#7897a4;font-size:9px;letter-spacing:1.3px}.score-grid b{display:block;font:700 19px 'Barlow Condensed';margin-top:4px;color:#e1fbff}.damage-flash{position:absolute;inset:0;z-index:5;pointer-events:none;background:radial-gradient(ellipse,transparent 35%,rgba(255,32,28,.55));opacity:0;transition:opacity .15s}.mobile-controls{display:none}.fire-btn,.boost-btn,.steer-pad button{border:1px solid #9defff80;background:#07131dcc;backdrop-filter:blur(8px);color:var(--cyan);font-weight:800;touch-action:none}.steer-pad{display:flex;gap:8px}.steer-pad button{width:54px;height:54px;font-size:32px;border-radius:50%}.fire-btn{width:62px;height:62px;border-radius:50%;background:#21cee455;font-size:11px}.boost-btn{width:49px;height:49px;border-radius:50%;font-size:10px;border-color:#ffb36b;color:#ffb36b}
@media(max-width:760px){.topbar{height:58px;padding:12px 16px}.brand{font-size:17px}.brand-mark{width:29px;height:29px}.mission-tag{font-size:9px;letter-spacing:.7px}.mission-tag span{display:none}.icon-btn{padding:5px 7px}.icon-btn span{display:none}.hud{inset:67px 17px 0}.hud-left{gap:12px}.readout{min-width:94px}.readout strong{font-size:27px}.distance-readout{padding-left:10px}.distance-readout strong{font-size:21px}.objective{top:73px;left:0;transform:none}.objective strong{font-size:11px}.objective small{font-size:8px}.hud-right{top:0;gap:10px}.weapon{display:none}.wave{font-size:8px}.vitals,.nitro{width:125px;bottom:120px}.bottom-hint{display:none}.mobile-controls{position:absolute;display:flex;z-index:4;left:18px;right:18px;bottom:20px;align-items:end;justify-content:space-between;pointer-events:none}.mobile-controls button{pointer-events:auto}.fire-btn{margin-left:auto;margin-right:14px}.overlay{background:linear-gradient(90deg,rgba(4,9,16,.89),rgba(4,9,16,.46))}.intro-card{margin:0;width:min(430px,88vw);padding-top:20px}.intro-card h1{font-size:clamp(72px,19vw,108px);margin:23px 0 16px}.briefing{font-size:12px;max-width:360px}.side-stats{display:none}.controls-note{font-size:8px;white-space:normal;line-height:1.7;max-width:345px}.version{left:16px;bottom:8px}.end-card{padding:25px}.end-card h2{font-size:41px}.crosshair{display:none!important}}@media(max-height:600px) and (min-width:761px){.intro-card{transform:scale(.84);transform-origin:left center}.hud{top:68px}.vitals,.nitro{bottom:25px}}

(() => {
  'use strict';
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const ui = { intro: $('#intro'), end: $('#end-screen'), start: $('#start-btn'), retry: $('#retry-btn'), speed: $('#speed'), speedFill: $('#speed-fill'), distance: $('#distance'), armorFill: $('#armor-fill'), armor: $('#armor-value'), nitroFill: $('#nitro-fill'), nitroLabel: $('#nitro-label'), threat: $('#threat'), toast: $('#toast'), flash: $('#damage-flash'), crosshair: $('#crosshair'), objective: $('#objective-sub'), title: $('#end-title'), copy: $('#end-copy'), finalDistance: $('#final-distance'), finalKills: $('#final-kills'), finalSpeed: $('#final-speed'), sound: $('#sound-btn') };
  let W = 0, H = 0, dpr = 1, running = false, last = 0, time = 0;
  let game = {};
  const keys = new Set();
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const rand = (a, b) => a + Math.random() * (b - a);
  const resize = () => { W = innerWidth; H = innerHeight; dpr = Math.min(devicePixelRatio || 1, 1.6); canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr); ctx.setTransform(dpr, 0, 0, dpr, 0, 0); };
  addEventListener('resize', resize); resize();
  const init = () => { game = { dist: 0, speed: 80, top: 80, armor: 100, nitro: 100, lane: 0, steer: 0, enemies: [], particles: [], kills: 0, spawn: 0, shake: 0, fire: 0, rocket: 0, invuln: 0, toast: 0, muted: true, mouse: { x: W * .5, y: H * .56 }, stars: Array.from({length: 90}, () => ({x:Math.random(),y:Math.random()*.32,r:Math.random()*1.4,a:rand(.2,.8)})), buildings: makeCity() }; };
  function makeCity(){ return Array.from({length:34},(_,i)=>({x:i/34, w:rand(.012,.036), h:rand(.04,.19), seed:Math.random(), hue:Math.random()})); }
  init();

  function project(lane, dist){
    const horizon = H * .31, depth = H * .74;
    const p = clamp(1 - dist / 900, 0, 1);
    const curve = Math.sin(game.dist * .00035) * (1-p) * W * .035;
    const roadHalf = W * (.055 + .39 * p);
    const center = W*.5 + curve;
    return { x:center + lane * roadHalf * .66, y:horizon + Math.pow(p,1.62)*depth, scale:.12 + p*1.16, p, center, roadHalf };
  }
  function polygon(points, color){ ctx.fillStyle=color; ctx.beginPath(); points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y)); ctx.closePath(); ctx.fill(); }
  function drawBackground(){
    const sky=ctx.createLinearGradient(0,0,0,H*.68); sky.addColorStop(0,'#070d1b');sky.addColorStop(.55,'#14223a');sky.addColorStop(1,'#674448');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    const glow=ctx.createRadialGradient(W*.5,H*.33,3,W*.5,H*.33,W*.43);glow.addColorStop(0,'#ff81532b');glow.addColorStop(1,'#ff815300');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H*.65);
    for(const s of game.stars){ctx.globalAlpha=s.a;ctx.fillStyle='#b8e4ff';ctx.fillRect(s.x*W,s.y*H,s.r,s.r);}ctx.globalAlpha=1;
    const horizon=H*.31, offset=(game.dist*.00013)%1;
    game.buildings.forEach((b,i)=>{const x=(b.x*W + offset*W*.075 + W)%W;const h=b.h*H;const y=horizon-h;const grad=ctx.createLinearGradient(x,y,x,y+h);grad.addColorStop(0,'#101d2b');grad.addColorStop(1,'#0a111a');ctx.fillStyle=grad;ctx.fillRect(x,y,b.w*W,h);ctx.fillStyle=b.hue>.78?'#ff785147':'#60dff043';for(let wy=y+10;wy<horizon-6;wy+=11){for(let wx=x+4;wx<x+b.w*W-3;wx+=8){if((Math.floor(wx+wy+b.seed*400)%5)!==0)ctx.fillRect(wx,wy,2,3);}}});
    // distant elevated highway and lamps
    ctx.strokeStyle='#4ca6b355';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,horizon+6);ctx.lineTo(W,horizon+6);ctx.stroke();
    for(let i=0;i<9;i++){let x=((i/8)*W - (game.dist*.00045%1)*W*.12+W)%W;ctx.fillStyle='#83edff';ctx.shadowColor='#45d9ff';ctx.shadowBlur=10;ctx.fillRect(x,horizon-42,2,42);ctx.shadowBlur=0;ctx.fillStyle='#ff744e';ctx.fillRect(x-1,horizon-44,4,2);}
  }
  function drawRoad(){
    const horizon=H*.31, bottom=H+30, curve=Math.sin(game.dist*.00035)*W*.035;
    const topHalf=W*.055, botHalf=W*.445;
    polygon([[W*.5+curve-topHalf,horizon],[W*.5+curve+topHalf,horizon],[W*.5+curve+botHalf,bottom],[W*.5+curve-botHalf,bottom]],'#20262c');
    polygon([[W*.5+curve-topHalf*.86,horizon],[W*.5+curve+topHalf*.86,horizon],[W*.5+curve+botHalf*.86,bottom],[W*.5+curve-botHalf*.86,bottom]],'#292e31');
    // scrolling asphalt texture
    for(let i=0;i<40;i++){const f=((i/40 + (game.dist*.0009)%1)%1);const y=horizon+Math.pow(f,1.55)*(bottom-horizon);const half=topHalf+(botHalf-topHalf)*f;const x=W*.5+curve*f;ctx.fillStyle=`rgba(190,205,196,${.015+f*.02})`;ctx.fillRect(x-half+Math.sin(i*31)*half*.45,y,2+f*3,1+f*2);}
    for(const sign of [-1,1]){
      polygon([[W*.5+curve+sign*topHalf*.91,horizon],[W*.5+curve+sign*topHalf*1.06,horizon],[W*.5+curve+sign*botHalf*1.04,bottom],[W*.5+curve+sign*botHalf*.88,bottom]],'#8f433c');
      polygon([[W*.5+curve+sign*topHalf*1.06,horizon],[W*.5+curve+sign*topHalf*1.11,horizon],[W*.5+curve+sign*botHalf*1.08,bottom],[W*.5+curve+sign*botHalf*1.04,bottom]],'#d5d3b8');
    }
    const phase=(game.dist*.0017)%1;
    for(let lane=-1;lane<=1;lane+=2){for(let i=0;i<14;i++){const f=((i/14+phase)%1);const y=horizon+Math.pow(f,1.58)*(bottom-horizon);const half=topHalf+(botHalf-topHalf)*f;const x=W*.5+curve*f+lane*half*.33;const len=4+f*34;ctx.fillStyle=`rgba(190,225,222,${.2+f*.42})`;ctx.fillRect(x-1,y,2+f*2,len);}}
    // passing roadside pylons
    for(let i=0;i<7;i++){const f=((i/7+(game.dist*.0011)%1)%1);const y=horizon+Math.pow(f,1.6)*(bottom-horizon);const half=topHalf+(botHalf-topHalf)*f;for(const side of [-1,1]){const x=W*.5+curve*f+side*(half+5+f*19);const scale=.2+f*.9;ctx.fillStyle='#334750';ctx.fillRect(x-2*scale,y-28*scale,4*scale,30*scale);ctx.fillStyle=i%2?'#ff744a':'#5beaff';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=8*scale;ctx.fillRect(x-4*scale,y-28*scale,8*scale,3*scale);ctx.shadowBlur=0;}}
    // edge glow
    ctx.strokeStyle='#42d7ed45';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(W*.5+curve-topHalf,horizon);ctx.lineTo(W*.5+curve-botHalf,bottom);ctx.moveTo(W*.5+curve+topHalf,horizon);ctx.lineTo(W*.5+curve+botHalf,bottom);ctx.stroke();
  }
  function drawEnemy(e){
    const p=project(e.lane,e.dist), s=p.scale; if(e.dist>900||p.y>H+30)return;
    const x=p.x,y=p.y, w=35*s*(e.type==='brute'?1.35:1), h=30*s*(e.type==='brute'?1.2:1);
    ctx.save();ctx.translate(x,y);ctx.shadowColor=e.flash?'#fff':'#c94cff';ctx.shadowBlur=e.flash?22:9*s;
    // glowing hover body
    ctx.fillStyle=e.flash?'#fff':(e.type==='brute'?'#9e4dc1':'#713d9c');ctx.beginPath();ctx.moveTo(-w*.65,-h*.15);ctx.lineTo(-w*.42,-h*.58);ctx.lineTo(-w*.12,-h*.75);ctx.lineTo(w*.37,-h*.56);ctx.lineTo(w*.65,-h*.16);ctx.lineTo(w*.48,h*.08);ctx.lineTo(-w*.48,h*.08);ctx.closePath();ctx.fill();
    ctx.shadowBlur=0;ctx.fillStyle='#e3adff';ctx.fillRect(-w*.17,-h*.51,w*.34,h*.09);ctx.fillStyle='#ff443f';ctx.fillRect(-w*.5,h*.02,w*.16,h*.07);ctx.fillRect(w*.34,h*.02,w*.16,h*.07);
    ctx.fillStyle='#3c234f';ctx.beginPath();ctx.ellipse(0,h*.12,w*.48,h*.15,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e24fff';ctx.fillRect(-w*.15,h*.12,w*.3,Math.max(1,2*s));
    if(e.hp>1){ctx.fillStyle='#16141f';ctx.fillRect(-w*.4,-h*.92,w*.8,3*s);ctx.fillStyle='#ff5b56';ctx.fillRect(-w*.4,-h*.92,w*.8*(e.hp/2),3*s);}
    ctx.restore();
  }
  function drawCar(){
    const x=W*.5+game.lane*W*.16+Math.sin(game.dist*.00035)*W*.035, y=H*.87, scale=Math.min(1,W/1000);game.carX=x;
    ctx.save();ctx.translate(x,y);ctx.scale(scale,scale); if(game.shake>0)ctx.translate(rand(-game.shake,game.shake),rand(-game.shake,game.shake));
    // nitro trail
    if(keys.has('Shift')&&game.nitro>0){for(let i=0;i<5;i++){ctx.fillStyle=i%2?'#36caff88':'#ffb24c99';ctx.beginPath();ctx.moveTo(-30+i*15,18);ctx.lineTo(-24+i*15,18);ctx.lineTo(-27+i*15,rand(45,76));ctx.closePath();ctx.fill();}}
    ctx.shadowColor='#00cfff';ctx.shadowBlur=22;ctx.fillStyle='#111b22';ctx.beginPath();ctx.moveTo(-65,16);ctx.lineTo(-57,-20);ctx.lineTo(-42,-39);ctx.lineTo(-24,-44);ctx.lineTo(26,-44);ctx.lineTo(50,-30);ctx.lineTo(61,5);ctx.lineTo(52,21);ctx.lineTo(-54,21);ctx.closePath();ctx.fill();ctx.shadowBlur=0;
    // tires / chassis
    ctx.fillStyle='#090d10';ctx.fillRect(-59,-11,13,31);ctx.fillRect(47,-11,13,31);ctx.fillStyle='#69736f';ctx.fillRect(-58,-3,8,13);ctx.fillRect(50,-3,8,13);
    polygon([[-44,-28],[-29,-40],[21,-40],[40,-29],[49,2],[-49,2]],'#88928a');polygon([[-30,-35],[-20,-44],[19,-44],[32,-34]],'#314550');
    // cockpit and armor plating
    polygon([[-17,-36],[18,-36],[26,-20],[-23,-20]],'#14242c');ctx.strokeStyle='#67e5ee';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-18,-35);ctx.lineTo(-24,-20);ctx.lineTo(27,-20);ctx.lineTo(19,-35);ctx.stroke();
    ctx.fillStyle='#bcc2ae';ctx.fillRect(-47,-16,94,5);ctx.fillStyle='#f6cc73';ctx.fillRect(-47,-16,13,4);ctx.fillRect(34,-16,13,4);ctx.fillStyle='#ff4d42';ctx.fillRect(-42,6,13,4);ctx.fillRect(29,6,13,4);
    // turret and barrel
    ctx.fillStyle='#59635f';ctx.fillRect(-5,-52,10,14);ctx.fillStyle='#87938b';ctx.fillRect(-11,-54,22,6);ctx.fillStyle='#2c3f48';ctx.fillRect(-2,-66,4,16);ctx.fillStyle='#ffbb56';ctx.fillRect(-2,-67,4,2);
    ctx.restore();
  }
  function drawParticles(){for(const p of game.particles){ctx.globalAlpha=clamp(p.life,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}
